-- Motorcycle Comparison API - Brazil/FIPE motorcycle seed
-- Generated from the FIPE snapshot 08/2026 previously supplied in this conversation.
-- Rows in source dataset: 8395
-- FX used for motorcycles.price_eur: 1 BRL = 0.1666 EUR on 2026-08-24.
-- Category is mandatory in the application schema but absent from FIPE. It is assigned by
-- deterministic family/keyword rules. See motos_brasil_category_audit_2026-08.csv before production use.
-- Technical fields are NOT guessed. engine_specifications.displacement_cc is populated only when
-- the FIPE model descriptor itself explicitly contains a value suffixed by cc/ccm; other unavailable
-- values remain NULL. Electric powertrains receive engine_type='Electric'.
-- motorcycle_additional_specs contains only rider-facing facts (Fuel and Reference price (BRL)).
-- This script is rerunnable: existing (brand, model, model_year) combinations are left untouched.

BEGIN;

CREATE TEMP TABLE tmp_motorcycle_fipe_import (
    row_no bigint PRIMARY KEY,
    brand varchar(60) NOT NULL,
    model varchar(120) NOT NULL,
    model_year integer NOT NULL,
    category varchar(20) NOT NULL,
    price_eur numeric(10,2),
    price_brl numeric(12,2),
    fuel_type varchar(40),
    fipe_code varchar(20),
    base_slug varchar(160) NOT NULL,
    slug varchar(160),
    explicit_cc integer,
    engine_id bigint,
    motorcycle_id bigint
) ON COMMIT DROP;






















-- Rerun safety: preserve richer rows that already exist in dev/prod.
DELETE FROM tmp_motorcycle_fipe_import s
WHERE EXISTS (
    SELECT 1
    FROM motorcycles m
    WHERE lower(m.brand) = lower(s.brand)
      AND lower(m.model) = lower(s.model)
      AND m.model_year = s.model_year
);

-- Verify identity/serial sequences before preallocating the 1:1 engine FK IDs.
DO $$
BEGIN
    IF pg_get_serial_sequence('engine_specifications', 'id') IS NULL THEN
        RAISE EXCEPTION 'engine_specifications.id has no serial/identity sequence';
    END IF;
    IF pg_get_serial_sequence('motorcycles', 'id') IS NULL THEN
        RAISE EXCEPTION 'motorcycles.id has no serial/identity sequence';
    END IF;
END $$;

-- Resolve stable slugs against both existing catalogue rows and this import. Numeric suffixes
-- mirror the service-side disambiguation policy. Rows are processed deterministically by row_no.
DO $$
DECLARE
    r record;
    candidate varchar(160);
    suffix integer;
BEGIN
    FOR r IN
        SELECT row_no, base_slug
        FROM tmp_motorcycle_fipe_import
        ORDER BY row_no
    LOOP
        candidate := r.base_slug;
        suffix := 2;

        WHILE EXISTS (SELECT 1 FROM motorcycles m WHERE m.slug = candidate)
           OR EXISTS (
                SELECT 1
                FROM tmp_motorcycle_fipe_import s
                WHERE s.row_no < r.row_no
                  AND s.slug = candidate
           )
        LOOP
            candidate := left(r.base_slug, 160 - length(suffix::text) - 1) || '-' || suffix::text;
            suffix := suffix + 1;
        END LOOP;

        UPDATE tmp_motorcycle_fipe_import
        SET slug = candidate
        WHERE row_no = r.row_no;
    END LOOP;
END $$;

-- Allocate IDs from the real PostgreSQL identity sequences so this can coexist with IDs 1-99
-- reserved by the current dev seed.
UPDATE tmp_motorcycle_fipe_import
SET engine_id = nextval(pg_get_serial_sequence('engine_specifications', 'id')::regclass),
    motorcycle_id = nextval(pg_get_serial_sequence('motorcycles', 'id')::regclass);

-- Required API-side 1:1 engine block. Unknown technical values deliberately remain NULL.
    id,
    engine_type,
    displacement_cc
)
SELECT
    engine_id,
    CASE WHEN fuel_type = 'Elétrico' THEN 'Electric' WHEN fuel_type = 'Híbrido' THEN 'Hybrid' ELSE NULL END,
    explicit_cc
FROM tmp_motorcycle_fipe_import
ORDER BY row_no;

-- Dimensions are optional in the schema and are not created as empty placeholder rows.
    id,
    slug,
    version,
    brand,
    model,
    model_year,
    category,
    price_eur,
    image_url,
    description,
    frame_type,
    front_suspension,
    rear_suspension,
    front_brake,
    rear_brake,
    abs_type,
    front_tyre,
    rear_tyre,
    engine_specification_id,
    dimension_id,
    created_at,
    updated_at
)
SELECT
    motorcycle_id,
    slug,
    0,
    brand,
    model,
    model_year,
    category,
    price_eur,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    engine_id,
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM tmp_motorcycle_fipe_import
ORDER BY row_no;

-- Public, rider-facing long-tail facts only. No source URLs, import IDs or provenance are exposed.
SELECT motorcycle_id, 'Fuel', fuel_type
FROM tmp_motorcycle_fipe_import
WHERE fuel_type IS NOT NULL AND btrim(fuel_type) <> ''
UNION ALL
SELECT motorcycle_id, 'Reference price (BRL)', to_char(price_brl, 'FM999999990.00')
FROM tmp_motorcycle_fipe_import
WHERE price_brl IS NOT NULL;

-- Defensive checks before commit.
DO $$
DECLARE
    bad_count bigint;
BEGIN
    SELECT count(*) INTO bad_count
    FROM tmp_motorcycle_fipe_import s
    LEFT JOIN motorcycles m ON m.id = s.motorcycle_id
    LEFT JOIN engine_specifications e ON e.id = s.engine_id
    WHERE m.id IS NULL OR e.id IS NULL OR m.engine_specification_id <> e.id;

    IF bad_count <> 0 THEN
        RAISE EXCEPTION 'Seed integrity check failed for % imported rows', bad_count;
    END IF;
END $$;

COMMIT;
